const runIndex = $runIndex;
const productImage = $('When Executed by Another Workflow').item.json.product_image;
const influencerImage = $node['influencer_image_to_base_64'].json.data;

let promptText;

if (runIndex % 2 === 0) {
  // Before/After prompt - ALWAYS FRONT FACING
  promptText = 'Create a professional before/after split-screen comparison image. LEFT SIDE (BEFORE): Use the person from image 2 with their natural hair. RIGHT SIDE (AFTER): Show the EXACT SAME person wearing the EXACT hair extensions from image 1.

CRITICAL PRODUCT ACCURACY REQUIREMENTS:
- The hair extensions MUST be IDENTICAL to image 1: exact color, exact texture, exact length, exact style
- DO NOT modify, reinterpret, or stylize the product - replicate it PRECISELY
- Match every detail: color tone, highlights, wave pattern, thickness, shine level
- The extensions should look like the ACTUAL product from image 1 is on the person from image 2
- NO artistic interpretation - this is product documentation

POSE REQUIREMENTS (CRITICAL):
- BOTH BEFORE and AFTER: Person MUST face directly forward toward camera
- BOTH sides: Straight-on front view, shoulders square to camera
- BOTH sides: Eyes looking directly at camera
- BOTH sides: Neutral to slight smile, professional portrait pose
- NO side angles, NO three-quarter views, NO back views
- Hair should be visible from front view (can cascade over shoulders)
- Same exact pose and angle on both BEFORE and AFTER sides

OTHER REQUIREMENTS:
- Split canvas 50/50 vertically with thin white divider
- Add BEFORE (top left) and AFTER (top right) in elegant serif font
- BEFORE: person with natural shorter hair, front facing
- AFTER: same person, same face, same outfit, same front-facing pose, EXACT product from image 1
- Same background and lighting on both sides - soft, neutral backdrop
- Add small rectangular branding at bottom center: "ZEN HAIR EXTENSIONS" (black text on white background, English only)
- Professional beauty photography quality

Output only the final composite image.';
} else {
  // Lifestyle photo with VARIED ANGLES + ARABIC TEXT
  const angleVariation = Math.floor(runIndex / 2) % 5;
  const taglineIndex = Math.floor(runIndex / 2) % 6;

  const taglines = [
    { arabic: 'سحر فوري، بلا جهد', transliteration: 'Effortless Glamour, Instantly' },
    { arabic: 'شعرك المثالي، كل يوم', transliteration: 'Your Best Hair, Every Day' },
    { arabic: 'طول. كثافة. ثقة', transliteration: 'Length. Volume. Confidence' },
    { arabic: 'تحول في ثوانٍ', transliteration: 'Transform in Seconds' },
    { arabic: 'شعر فاخر، بسهولة تامة', transliteration: 'Luxurious Hair, Made Easy' },
    { arabic: 'سحر بلا حدود', transliteration: 'Glamour Without Limits' }
  ];

  const angles = [
    'front view facing camera with hair framing the face, confident smile',
    'side profile view showing the full hair length and volume cascading down',
    'back view showcasing the complete length, texture and flow of the hair',
    'three-quarter angle showing both face and hair flowing naturally over shoulder',
    'dynamic pose with hair in gentle motion, hand naturally touching or running through hair'
  ];

  const selectedTagline = taglines[taglineIndex];

  promptText = 'Create a realistic lifestyle photograph showing the person from image 2 wearing the EXACT hair extensions from image 1.

CRITICAL PRODUCT ACCURACY REQUIREMENTS:
- The hair extensions MUST be PIXEL-PERFECT replicas of image 1
- EXACT color match - including undertones, highlights, and color depth from image 1
- EXACT texture match - wave pattern, curl type, straightness from image 1
- EXACT length match - do not shorten or lengthen from image 1
- EXACT thickness/volume match from image 1
- EXACT shine/gloss level from image 1
- This is PRODUCT PHOTOGRAPHY - accuracy is more important than artistic beauty
- The person should look like they are wearing the ACTUAL physical product from image 1
- NO modifications, NO reinterpretation, NO stylization of the product

SETTING:
- Elegant outdoor or upscale indoor location
- Person looks confident and naturally glamorous
- Hair clearly visible and well-lit
- Camera angle: ' + angles[angleVariation] + '
- Natural golden hour or soft diffused lighting
- Premium lifestyle aesthetic

PERSON:
- Use exact facial features, skin tone, ethnicity from image 2
- Professional but authentic lifestyle feel

ARABIC TEXT OVERLAY (TOP CENTER) - CRITICAL:
- Display this ARABIC text prominently: "' + selectedTagline.arabic + '"
- Font: Elegant Arabic calligraphy font (like Diwani or modern Arabic display font)
- Style: White or light cream colored text with subtle shadow for readability
- Text MUST be RIGHT-TO-LEFT Arabic script
- Ensure proper Arabic character formation and letter joining
- Center-aligned, large and clearly readable
- Premium, sophisticated look matching luxury advertisement
- Place at top center of image with good contrast against background
- NO English text in the main tagline area
- ONLY add "ZEN HAIR EXTENSIONS" in small English text at bottom if space permits
- NO other watermarks or labels

IMPORTANT: The Arabic text must be INTEGRATED into the image naturally, not looking like a separate overlay. It should feel like part of the advertisement design.

Output only the final image with Arabic tagline.';
}

const requestBody = {
  contents: [
    {
      parts: [
        {
          text: promptText
        },
        {
          inline_data: {
            mime_type: "image/png",
            data: productImage
          }
        },
        {
          inline_data: {
            mime_type: "image/jpeg",
            data: influencerImage
          }
        }
      ]
    }
  ]
};

return {
  json: {
    requestBody: JSON.stringify(requestBody)
  }
};
